Here, we are creating unmodifiable list in Java 9.
package com.tutorialspoint;
import java.util.List;
public class Tester {
   public static void main(String[] args){
	   List<String> list =  List.of("Java","HTML 5","C");
	   System.out.println(list);
   }  
